style.css:
@-moz-document domain("youtube.com") {
:root {
    --main-color: #ffa420;
    --bg-url: url('https://images4.alphacoders.com/131/thumb-1920-1311016.png');
}

/* ===== FONDO ===== */

html,
body > div,
body > table,
[role="navigation"],
[role="dialog"],
#body-container > div,
[aria-expanded="true"]:not(.ytp-button),
[class*="tooltip"]:not(.ytp-tooltip-duration):not(.ytp-tooltip-bg):not(.ytp-tooltip-text-wrapper):not([class*="arrow"]):not(button),
[role="menu"],
.ytp-popup,
.videoAdUiPreSkipButton,
.videoAdUiAdInfoPopup,
ytd-app,
#content,
#page-manager,
ytd-browse,
ytd-watch-flexy,
#columns,
#primary,
#secondary {
    background: var(--bg-url) fixed #000 !important;
    background-size: cover !important;
    background-position: center center !important;
}

/* Hacer transparentes los contenedores principales */

ytd-app,
#content,
#page-manager,
ytd-browse,
ytd-watch-flexy,
#columns,
#primary,
#secondary,
#guide-content,
ytd-mini-guide-renderer,
#masthead-container,
#header,
ytd-rich-grid-renderer,
ytd-item-section-renderer {
    background-color: transparent !important;
    background: transparent !important;
}

/* ========== ARRIBA FORZADO TRANSPARENTE ========== */

html,
html[dark],
[dark],
ytd-app,
ytd-masthead {
    --yt-spec-base-background: transparent !important;
    --yt-spec-brand-background-primary: transparent !important;
    --yt-spec-brand-background-solid: transparent !important;
    --yt-spec-general-background-a: transparent !important;
    --yt-spec-general-background-b: transparent !important;
    --yt-spec-general-background-c: transparent !important;
    --yt-spec-raised-background: transparent !important;
    --yt-spec-menu-background: transparent !important;
    --yt-frosted-glass-desktop: transparent !important;
    --yt-spec-static-brand-red: transparent !important;
}

#masthead-container,
#masthead-container.ytd-app,
ytd-masthead,
ytd-masthead#masthead,
#container.ytd-masthead,
ytd-masthead #container,
#background.ytd-masthead,
#frosted-glass,
#frosted-glass.with-chipbar,
#chips-wrapper,
ytd-feed-filter-chip-bar-renderer,
#header-bar,
[role="banner"] {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
    box-shadow: none !important;
    border: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

#background.ytd-masthead {
    display: none !important;
    opacity: 0 !important;
    visibility: hidden !important;
}

/* Semi-transparente SOLO en el área de contenido */

#primary,
#secondary,
ytd-watch-flexy[theater] #player-theater-container {
    background-color: rgba(0, 0, 0, 0.12) !important;
}

/* ===== COLORES ===== */

:not(textarea):not(input):not([contenteditable]) {
    text-shadow: 0 0.05em rgba(0,0,0,.5), 0 -0.05em rgba(0,0,0,.0), 0.05em 0 rgba(0,0,0,.0), -0.05em 0 rgba(0,0,0,.5) !important;
}

/* Texto normal */

:not([class*="video-extras-sparkbar"]):not([class^="ytp-"]):not(.sidebar):not(.video-time):not([class^="html5-"]):not(.yt-uix-button-primary):not(label):not(.toggle):not(.branding-context-container-inner):not(.iv-drawer) {
    background-color: transparent !important;
    color: #f0f0f0 !important;
}

/* Enlaces */

:link {
    color: #7dd3fc !important;
}

:visited {
    color: #a5b4fc !important;
}

/* Títulos y textos importantes */

#video-title,
.ytd-video-meta-block,
.ytd-channel-name,
yt-formatted-string,
#text {
    color: #ffa420 !important;
}

/* ===== BARRA DE BÚSQUEDA ===== */

#masthead-search-terms,
form.channels-search {
    border: 1px solid #FFF !important;
}

#masthead-search-terms.gsfe_a {
    border: 1px solid #A0A0A0 !important;
}

#masthead-search-terms.gsfe_b {
    border: 1px solid var(--main-color) !important;
}

/* ===== ICONOS ===== */

[href="/"][id*="logo"],
:not(.ytp-volume-slider-handle):not(.yt-uix-playlistlike):before,
.yt-uix-button-icon-material-upload,
.yt-uix-button-icon-bell,
.yt-uix-button-icon-wrapper > .yt-sprite,
.autoplay-info-icon,
.search-button > .yt-uix-button-content,
#appbar-guide-button .yt-uix-button-icon-wrapper,
.yt-uix-button-shelf-slider-pager {
    filter: invert(1) hue-rotate(180deg);
}

/* ===== OTROS AJUSTES ===== */

.load-more-button {
    background: transparent !important;
}

[role="alert"],
.content-region,
.yt-uix-checkbox-on-off .checked:before {
    display: none !important;
}

select {
    background: black !important;
}

.yt-uix-form-input-select,
[class$="container"],
#yt-comments-paginator {
    background-image: none !important;
}

:not(h2):not(button):not(.comment-simplebox-renderer-collapsed-content),
#footer-container button,
.yt-uix-button-shelf-slider-pager {
    border: none !important;
}

textarea,
[contenteditable="true"],
[type="text"]:not(#masthead-search-term),
[role="menu"]:not(.guide-user-links):not(.ytp-panel-menu),
#footer-container .yt-uix-button-default,
.yt-uix-clickcard-card-visible,
#watch-appbar-playlist,
.comment-simplebox-frame,
body > table {
    box-shadow: inset 0px 0px 0px 1px rgba(255,255,255,.5) !important;
}

#masthead-search-terms {
    box-shadow: none !important;
}
}
